const ELEMENT_GROUP_FACTS = [
  ['intro', '주기율표 18족에 속하며 화학적으로 매우 안정해 다른 원소와 거의 반응하지 않는 원소군(헬륨, 네온, 아르곤 등)을 무엇이라 하는가?', '비활성 기체', '원자가 전자가 꽉 차 있어 반응성이 극히 낮습니다.', '18족 원소는 비활성 기체(영족 기체)로 불리며 헬륨·네온·아르곤·크립톤·제논·라돈·오가네손이 속합니다.'],
  ['intro', '주기율표 1족 중 수소를 제외한 리튬, 나트륨, 칼륨 등 물과 격렬히 반응하는 금속 원소군을 무엇이라 하는가?', '알칼리 금속', '물에 녹으면 강한 염기성(알칼리성)을 띱니다.', '1족의 리튬·나트륨·칼륨·루비듐·세슘·프랑슘은 알칼리 금속으로 반응성이 매우 큽니다.'],
  ['beginner', '주기율표 17족에 속하며 플루오린, 염소, 브로민, 아이오딘 등을 포함하는 반응성 큰 비금속 원소군은?', '할로젠', '금속과 쉽게 결합해 소금 같은 염(Salt)을 만듭니다.', '할로젠(17족)은 원자가 전자가 7개로 전자 1개를 얻어 음이온이 되려는 성질이 강합니다.'],
  ['beginner', '베릴륨, 마그네슘, 칼슘, 스트론튬, 바륨 등이 속한 주기율표 2족 원소군을 무엇이라 하는가?', '알칼리 토금속', '2족 원소로 +2가 양이온이 되기 쉽습니다.', '2족 원소는 알칼리 토금속으로 지각에 산화물이나 탄산염 형태로 널리 존재합니다.'],
  ['beginner', '금속과 비금속의 중간 성질을 띠며 규소, 붕소, 저마늄, 비소 등이 속하는 원소 분류는?', '준금속', '반도체 산업의 핵심 재료가 여기에 많습니다.', '준금속(반금속)은 조건에 따라 전기를 통하게 하거나 차단할 수 있어 반도체 소자에 활용됩니다.'],
  ['intermediate', '원자번호 57번 란타넘부터 71번 루테튬까지 15개 원소로 이루어지며 첨단 자석과 형광체에 쓰이는 원소군은?', '란타넘족', '주기율표 아래쪽 첫 번째 줄에 배치됩니다.', '란타넘족 15개 원소에 스칸듐·이트륨을 더한 17개 원소를 흔히 희토류 원소라 부릅니다.'],
  ['intermediate', '원자번호 89번 악티늄부터 103번 로렌슘까지 15개 원소로 이루어지며 모두 방사성을 띠는 원소군은?', '악티늄족', '우라늄과 플루토늄이 이 원소군에 속합니다.', '악티늄족은 주기율표 아래쪽 둘째 줄에 배치되며 모든 원소가 방사성 원소입니다.'],
  ['intermediate', '주기율표에서 3족부터 12족 사이에 위치하며 철, 구리, 금, 백금 등이 속하는 금속 원소군은?', '전이 금속', '촉매 작용이 뛰어나고 다양한 산화수를 가집니다.', '전이 금속은 d 오비탈에 전자가 채워지며 색을 띤 화합물을 잘 만들고 촉매로 널리 쓰입니다.'],
  ['intermediate', '란타넘족 15개 원소와 스칸듐(Sc), 이트륨(Y)을 합친 총 17개 원소를 통칭하는 용어는?', '희토류', '첨단 전자·전기차·방위 산업의 비타민으로 불립니다.', '희토류(Rare Earth Elements)는 지각 내 매장량 자체가 극히 적다기보다 경제적으로 채굴·정련하기 어려워 붙여진 이름입니다.'],
  ['advanced', '원자번호 92번 우라늄보다 원자번호가 커서 대부분 인공적으로 합성되는 93번 이후의 원소들을 통칭하는 용어는?', '초우라늄 원소', '넵투늄(93번)부터 시작합니다.', '초우라늄 원소는 우라늄(92번)보다 무거운 원소들로 모두 방사성이며 원자로 또는 입자가속기에서 생성됩니다.'],
  ['advanced', '루테늄, 로듐, 팔라듐, 오스뮴, 이리듐, 백금 등 촉매 성능과 내식성이 뛰어난 6개 귀금속을 묶어 부르는 명칭은?', '백금족 원소', '자동차 배기가스 촉매와 수소연료전지 핵심 소재입니다.', '백금족 원소(PGM)는 주기율표 8~10족의 5·6주기에 모여 있는 6개 귀금속입니다.'],
  ['advanced', '산소, 황, 셀레늄, 텔루륨 등이 속한 주기율표 16족 원소군을 일컫는 명칭은?', '칼코젠', '광석을 형성하는 원소라는 뜻의 그리스어에서 유래했습니다.', '16족 원소는 칼코젠(Chalcogen) 또는 산소족 원소라 부릅니다.'],
  ['advanced', '질소, 인, 비소, 안티모니, 비스무트가 속한 주기율표 15족 원소군을 일컫는 명칭은?', '프닉토젠', '질소족 원소로도 불립니다.', '15족 원소는 프닉토젠(Pnictogen)이라 부르며 원자가 전자가 5개입니다.'],
  ['intro', '현재 국제순수·응용화학연합(IUPAC)이 공식 인정한 주기율표의 총 원소 개수는 몇 개인가?', '118개', '1번 수소부터 118번 오가네손까지입니다.', '2016년 113·115·117·118번 원소의 공식 이름이 확정되면서 주기율표 7주기가 118개 원소로 완성되었습니다.'],
  ['beginner', '현대 주기율표에서 가로줄은 무엇을, 세로줄은 무엇을 나타내는가?', '가로줄은 주기, 세로줄은 족', '전자 껍질 수와 원자가 전자 수와 관련 있습니다.', '주기율표의 가로줄(1~7주기)은 전자 껍질 수를, 세로줄(1~18족)은 화학적 성질이 비슷한 원소들을 나타냅니다.'],
  ['beginner', '원자번호는 원자의 핵 속에 들어 있는 어떤 입자의 개수와 같은가?', '양성자', '양(+)전하를 띠는 원자핵 구성 입자입니다.', '원자번호(Z)는 원자핵 속 양성자 수이며 중성 원자에서는 전자 수와 같습니다.'],
  ['intermediate', '양성자 수는 같아 같은 원소이지만 중성자 수가 달라 질량수가 다른 원자들을 무엇이라 하는가?', '동위원소', '탄소-12와 탄소-14가 대표적 예입니다.', '동위원소는 화학적 성질은 거의 같지만 질량과 방사성 붕괴 여부가 다를 수 있습니다.'],
  ['intermediate', '다이아몬드와 흑연, 산소(O2)와 오존(O3)처럼 같은 한 가지 원소로 이루어졌지만 결합 구조가 달라 성질이 다른 물질을 무엇이라 하는가?', '동소체', '탄소 동소체에는 풀러렌과 그래핀도 있습니다.', '동소체(Allotrope)는 동일 원소의 원자 배열 차이로 물리적·화학적 성질이 크게 달라지는 현상입니다.'],
  ['advanced', '주기율표에서 같은 주기의 오른쪽 위로 갈수록 대체로 커지며, 원자가 공유결합 전자를 끌어당기는 힘의 척도는?', '전기음성도', '플루오린(F)이 약 3.98로 가장 큽니다.', '라이너스 폴링이 정량화한 전기음성도는 화학 결합의 극성을 판단하는 핵심 지표입니다.'],
  ['advanced', '기체 상태의 중성 원자 1몰에서 전자 1몰을 떼어내어 양이온으로 만드는 데 필요한 최소 에너지는?', '이온화 에너지', '비활성 기체가 같은 주기에서 가장 큽니다.', '이온화 에너지는 대체로 주기가 작고 오른쪽(18족)으로 갈수록 커집니다.']
];

function buildChemistrySection(add) {
  const allElementNames = ELEMENTS.map((e) => e[2]);
  const allElementSymbols = ELEMENTS.map((e) => e[1]);
  const allAtomicNums = ELEMENTS.map((e) => `${e[0]}번`);
  const elementCategories = [
    '비금속', '비활성 기체', '알칼리 금속', '알칼리 토금속', '할로젠',
    '준금속', '전이 금속', '전이후 금속', '란타넘족', '악티늄족',
    '희토류', '초우라늄 원소', '백금족 원소', '칼코젠', '프닉토젠'
  ];

  // Tier -> [name/symbol/fact diff, atomicNum diff]
  const tierDiff = {
    1: ['intro', 'beginner'],
    2: ['beginner', 'intermediate'],
    3: ['intermediate', 'advanced'],
    4: ['advanced', 'advanced']
  };

  for (const [num, sym, name, tier, cat, fact] of ELEMENTS) {
    const [baseDiff, numDiff] = tierDiff[tier];
    const nearbyNums = [];
    for (let d = -12; d <= 12; d++) {
      const n = num + d;
      if (n >= 1 && n <= 118 && n !== num) nearbyNums.push(`${n}번`);
    }
    const sameCatNames = ELEMENTS.filter((e) => e[4] === cat && e[2] !== name).map((e) => e[2]);
    const namePool = sameCatNames.length >= 6 ? sameCatNames : allElementNames;

    // 1. 원소명 -> 원소기호
    add(
      baseDiff,
      `원소 '${name}'의 원소 기호는 무엇인가?`,
      sym,
      allElementSymbols,
      `원자번호 ${num}번 원소이며 ${cat}에 속합니다.`,
      `${name}의 원소 기호는 ${sym}이며 원자번호는 ${num}번입니다. ${fact}입니다.`
    );

    // 2. 원소기호 -> 원소명
    add(
      baseDiff,
      `원소 기호 '${sym}'이(가) 나타내는 원소의 이름은 무엇인가?`,
      name,
      namePool,
      `원자번호 ${num}번의 ${cat} 원소입니다.`,
      `원소 기호 ${sym}은(는) 원자번호 ${num}번 원소인 ${name}을(를) 나타냅니다.`
    );

    // 3. 특징/활용 -> 원소명
    add(
      baseDiff,
      `${fact}은(는) 무엇인가?`,
      name,
      allElementNames,
      `원소 기호는 '${sym}', 원자번호는 ${num}번입니다.`,
      `${name}(${sym}, 원자번호 ${num}번)은(는) ${fact}입니다.`
    );

    // 4. 원자번호 -> 원소명
    add(
      numDiff,
      `주기율표에서 원자번호 ${num}번에 해당하는 원소는 무엇인가?`,
      name,
      allElementNames,
      `원소 기호는 '${sym}'이며 ${cat} 분류입니다.`,
      `원자번호 ${num}번 원소는 ${name}(${sym})입니다.`
    );

    // 5. 원소명 -> 원자번호 (tier 1~3 to keep count well-balanced)
    if (tier <= 3) {
      add(
        numDiff,
        `원소 '${name}(${sym})'의 원자번호는 몇 번인가?`,
        `${num}번`,
        nearbyNums.length >= 5 ? nearbyNums : allAtomicNums,
        `${cat}에 속하는 원소입니다.`,
        `${name}(${sym})의 원자번호는 ${num}번입니다.`
      );
    }

    // 6. 주요 원소 분류군 (알칼리 금속, 할로젠, 비활성 기체, 란타넘족, 악티늄족, 준금속 등) -> intermediate
    if (tier <= 3 && ['알칼리 금속', '알칼리 토금속', '할로젠', '비활성 기체', '준금속', '란타넘족', '악티늄족'].includes(cat)) {
      add(
        'intermediate',
        `원소 '${name}(${sym}, 원자번호 ${num}번)'은(는) 주기율표의 어느 원소 분류군에 속하는가?`,
        cat,
        ['비금속', '비활성 기체', '알칼리 금속', '알칼리 토금속', '할로젠', '준금속', '전이 금속', '전이후 금속', '란타넘족', '악티늄족'],
        `원자번호 ${num}번 원소의 족과 화학적 성질을 떠올려 보세요.`,
        `${name}(${sym})은(는) 주기율표에서 '${cat}'에 속하는 원소입니다.`
      );
    }
  }

  // Compounds
  const allCompNames = COMPOUNDS.map((c) => c[1]);
  const allCompFormulas = COMPOUNDS.map((c) => c[0]);
  for (const [formula, name, diff, desc] of COMPOUNDS) {
    const nextDiff = diff === 'intro' ? 'beginner' : diff === 'beginner' ? 'intermediate' : 'advanced';
    add(
      diff,
      `화학식 '${formula}'이(가) 나타내는 물질은 무엇인가?`,
      name,
      allCompNames,
      `${desc.slice(0, 26)}...`,
      `${formula}은(는) ${name}의 화학식입니다. ${desc}입니다.`
    );
    add(
      nextDiff,
      `'${name}'의 화학식으로 옳은 것은?`,
      formula,
      allCompFormulas,
      `${name}을(를) 이루는 원소 기호와 원자 수를 떠올려 보세요.`,
      `${name}의 화학식은 ${formula}입니다.`
    );
    add(
      diff,
      `${desc}은(는) 무엇인가?`,
      name,
      allCompNames,
      `화학식은 '${formula}'입니다.`,
      `${name}(${formula})은(는) ${desc}입니다.`
    );
  }

  // Group / concept questions
  const groupPool = [
    ...elementCategories,
    '118개', '112개', '108개', '120개', '92개', '104개',
    '가로줄은 주기, 세로줄은 족', '가로줄은 족, 세로줄은 주기', '가로줄은 질량, 세로줄은 밀도', '가로줄은 원자가, 세로줄은 원자핵', '가로줄은 산화수, 세로줄은 결합수',
    '양성자', '중성자', '전자', '쿼크', '광자', '중성미자',
    '동위원소', '동소체', '이성질체', '동중원소', '자유 라디칼', '착이온',
    '전기음성도', '이온화 에너지', '전자 친화도', '원자 반지름', '결합 에너지', '격자 에너지'
  ];
  for (const [diff, q, ans, hint, exp] of ELEMENT_GROUP_FACTS) {
    let pool = elementCategories;
    if (ans === '118개') pool = ['92개', '103개', '108개', '112개', '120개', '126개'];
    else if (ans.startsWith('가로줄')) pool = ['가로줄은 족, 세로줄은 주기', '가로줄은 질량, 세로줄은 밀도', '가로줄은 원자가, 세로줄은 원자핵', '가로줄은 산화수, 세로줄은 결합수', '가로줄은 원자량, 세로줄은 부피'];
    else if (ans === '양성자') pool = ['중성자', '전자', '광자', '중성미자', '글루온', '뮤온'];
    else if (ans === '동위원소' || ans === '동소체') pool = ['동위원소', '동소체', '이성질체', '동중원소', '다형체', '착이온', '중합체'];
    else if (ans === '전기음성도' || ans === '이온화 에너지') pool = ['전기음성도', '이온화 에너지', '전자 친화도', '원자 반지름', '결합 에너지', '격자 에너지', '활성화 에너지'];
    add(diff, q, ans, pool.length >= 5 ? pool : groupPool, hint, exp);
  }
}

