const ASTRO_EARTH_EXTRAS = [
  ['intro', '태양계 8개 행성을 태양에서 가까운 순서대로 바르게 나열한 것은?', '수성-금성-지구-화성-목성-토성-천왕성-해왕성', ['수성-화성-지구-금성-목성-토성-천왕성-해왕성', '금성-수성-지구-화성-목성-토성-해왕성-천왕성', '수성-금성-지구-화성-토성-목성-천왕성-해왕성', '수성-금성-화성-지구-목성-토성-천왕성-해왕성', '수성-금성-지구-화성-목성-토성-해왕성-천왕성'], '수금지화목토천해 순서를 떠올려 보세요.', '태양계 8행성은 태양에서 가까운 순으로 수성, 금성, 지구, 화성, 목성, 토성, 천왕성, 해왕성입니다.'],
  ['intro', '모스 굳기계(1~10)에서 굳기 10으로 가장 단단한 기준 광물은 무엇인가?', '금강석(다이아몬드)', ['강옥(커런덤)', '석영', '황옥(토파즈)', '활석', '방해석'], '탄소 원자가 정사면체 공유결합을 이룬 광물입니다.', '모스 굳기계는 1 활석에서 10 금강석(다이아몬드)까지 10단계 표준 광물로 상대적 경도를 측정합니다.'],
  ['beginner', '모스 굳기계(1~10)에서 굳기 1로 손톱으로도 쉽게 긁히는 가장 무른 기준 광물은?', '활석', ['석고', '방해석', '형석', '인회석', '정장석'], '베이비파우더 원료(탈크)로도 알려진 광물입니다.', '모스 굳기계 1단계는 활석(Talc), 2단계는 석고, 3단계는 방해석입니다.'],
  ['intro', '지구의 자전축은 공전 궤도면의 수직선에 대해 약 몇 도 기울어져 있어 사계절 변화가 생기는가?', '약 23.5도', ['약 0도', '약 10도', '약 45도', '약 66.5도', '약 98도'], '북회귀선과 남회귀선의 위도와 같습니다.', '지구 자전축이 약 23.5도(정확히는 약 23.44도) 기울어진 채 공전하기 때문에 태양 고도가 변해 계절이 생깁니다.'],
  ['beginner', '태양에서 출발한 빛이 지구에 도달하는 데 걸리는 시간은 약 얼마인가?', '약 8분 20초', ['약 1.3초', '약 1분', '약 40분', '약 1시간', '약 24시간'], '태양-지구 거리는 약 1억 5천만 km이고 광속은 초속 30만 km입니다.', '1억 4,960만 km ÷ 30만 km/s ≈ 약 499초, 즉 약 8분 19~20초가 걸립니다.'],
  ['beginner', '달에서 반사된 빛이나 무선 전파가 지구에 도달하는 데 걸리는 시간은 약 얼마인가?', '약 1.3초', ['약 0.01초', '약 13초', '약 8분 20초', '약 1분', '약 30초'], '지구-달 평균 거리는 약 38만 4천 km입니다.', '384,400 km ÷ 299,792 km/s ≈ 약 1.28초(약 1.3초)가 걸립니다.'],
  ['intermediate', '지질 시대 중 고생대·중생대·신생대를 통칭하며 현생 동물 화석이 풍부하게 나타나는 누대(Eon)는?', '현생누대', ['시생누대', '원생누대', '명왕누대', '선캄브리아대', '제4기'], '약 5억 4천만 년 전 캄브리아기부터 현재까지입니다.', '지구 역사는 명왕누대·시생누대·원생누대(이상 선캄브리아 시대)와 현생누대(고·중·신생대)로 구분됩니다.'],
  ['intermediate', '지구 역사상 해양 생물 종의 90% 이상이 사라져 가장 규모가 컸던 대멸종 사건은 어느 시대 말에 일어났는가?', '고생대 페름기 말', ['중생대 백악기 말', '고생대 캄브리아기 말', '중생대 쥐라기 말', '신생대 팔레오기 말', '선캄브리아대 말'], '약 2억 5,200만 년 전 시베리아 트랩 대규모 화산 분출과 관련이 깊습니다.', '페름기-트라이아스기(P-T) 대멸종은 지구 5대 대멸종 중 최대 규모로 삼엽충이 이때 완전히 멸종했습니다.'],
  ['beginner', '지구 대기에서 가장 많은 부피 비율(약 78%)을 차지하는 기체는?', '질소', ['산소', '아르곤', '이산화탄소', '수증기', '수소'], '산소는 약 21%, 아르곤은 약 0.93%입니다.', '건조한 지구 대기는 질소 약 78.08%, 산소 약 20.95%, 아르곤 약 0.93%, 이산화탄소 약 0.04%로 구성됩니다.'],
  ['intermediate', '항성의 표면 온도와 분광형에 따른 광도 분포를 나타낸 천문학의 대표 도표는?', 'H-R도(헤르츠스프룽-러셀 도표)', ['파인만 도표', '민코프스키 도표', '상평형 도표', '벤 다이어그램', '모스 도표'], '주계열성, 적색거성, 백색왜성 영역이 한눈에 나타납니다.', 'H-R도는 항성의 진화 단계와 물리적 성질을 분석하는 천체물리학의 핵심 도구입니다.'],
  ['advanced', '태양계 행성들의 분광형 분류(O, B, A, F, G, K, M)에서 표면 온도가 가장 높은 청백색 항성의 분광형은?', 'O형', ['A형', 'G형', 'K형', 'M형', 'F형'], 'Oh Be A Fine Girl/Guy, Kiss Me 암기법으로 유명합니다.', '항성 분광형은 고온에서 저온 순으로 O-B-A-F-G-K-M이며 태양은 G형(G2V)입니다.'],
  ['intermediate', '지구에서 관측할 때 태양의 표면 온도는 약 몇 도(K)인가?', '약 5,800K(약 5,500℃)', ['약 1,000K', '약 2,500K', '약 15,000K', '약 100만 K', '약 1,500만 K'], '태양 중심핵은 약 1,500만 K이지만 표면(광구)은 그보다 훨씬 낮습니다.', '태양 광구의 유효 온도는 약 5,778K(약 5,500℃)이며 코로나 온도는 100만 K 이상입니다.']
];

function buildAstroEarthSection(add) {
  // 1. Solar System
  const allSolarNames = SOLAR_SYSTEM.map((s) => s[0]);
  const allSolarDescs = SOLAR_SYSTEM.map((s) => s[4]);
  const planetParents = ['태양계 1번째 행성', '태양계 2번째 행성', '태양계 3번째 행성', '태양계 4번째 행성', '태양계 5번째 행성', '태양계 6번째 행성', '태양계 7번째 행성', '태양계 8번째 행성'];
  const moonParents = ['지구', '화성', '목성', '토성', '천왕성', '해왕성', '명왕성'];

  for (const [name, diff, type, parent, desc] of SOLAR_SYSTEM) {
    add(
      diff,
      `태양계의 천체 중 ${desc}은(는) 무엇인가?`,
      name,
      allSolarNames,
      `${parent}와(과) 관련된 ${type}입니다.`,
      `${name}은(는) ${desc}입니다.`
    );
    const nextDiff = diff === 'intro' ? 'beginner' : diff === 'beginner' ? 'intermediate' : 'advanced';
    add(
      nextDiff,
      `태양계 천체 '${name}'의 특징으로 옳은 것은?`,
      desc,
      allSolarDescs,
      `${type}에 해당하는 천체입니다.`,
      `${name}은(는) ${desc}입니다.`
    );
    if (type === '위성') {
      add(
        diff === 'intro' ? 'intro' : nextDiff,
        `태양계 위성 '${name}'은(는) 어느 행성(또는 왜소행성)의 위성인가?`,
        parent,
        moonParents,
        `${desc.slice(0, 26)}...`,
        `${name}은(는) ${parent}의 위성입니다.`
      );
    } else if (type === '행성') {
      add(
        'intro',
        `태양계에서 '${name}'은(는) 태양으로부터 몇 번째 행성인가?`,
        parent,
        planetParents,
        `수-금-지-화-목-토-천-해 순서를 떠올려 보세요.`,
        `${name}은(는) ${parent}입니다.`
      );
    }
  }

  // 2. Deep Space
  const allDeepNames = DEEP_SPACE.map((d) => d[0]);
  const allDeepDescs = DEEP_SPACE.map((d) => d[3]);
  for (const [name, diff, cat, desc] of DEEP_SPACE) {
    add(
      diff,
      `천문학(${cat})에서 ${desc}을(를) 무엇이라 하는가?`,
      name,
      allDeepNames,
      `${cat} 분야의 핵심 천체 또는 개념입니다.`,
      `${name}은(는) ${desc}입니다.`
    );
    const nextDiff = diff === 'intro' ? 'beginner' : diff === 'beginner' ? 'intermediate' : 'advanced';
    add(
      nextDiff,
      `천문학 용어 '${name}'에 대한 설명으로 옳은 것은?`,
      desc,
      allDeepDescs,
      `${cat}와(과) 관련된 천문학 개념입니다.`,
      `${name}은(는) ${desc}입니다.`
    );
  }

  // 3. Space Missions
  const allMissionNames = SPACE_MISSIONS.map((m) => m[0]);
  const allMissionDescs = SPACE_MISSIONS.map((m) => m[3]);
  for (const [name, diff, org, desc] of SPACE_MISSIONS) {
    add(
      diff,
      `우주 탐사 역사에서 ${desc}은(는) 무엇인가?`,
      name,
      allMissionNames,
      `${org}이(가) 주도하거나 관련된 우주 임무·기관입니다.`,
      `${name}(${org})은(는) ${desc}입니다.`
    );
    const nextDiff = diff === 'intro' ? 'beginner' : diff === 'beginner' ? 'intermediate' : 'advanced';
    add(
      nextDiff,
      `우주 개발·탐사와 관련된 '${name}'의 핵심 성과나 역할은?`,
      desc,
      allMissionDescs,
      `${org} 관련 우주 탐사 기록입니다.`,
      `${name}은(는) ${desc}입니다.`
    );
  }

  // 4. Earth Science
  const allEarthNames = EARTH_SCIENCE.map((e) => e[0]);
  const allEarthDescs = EARTH_SCIENCE.map((e) => e[3]);
  for (const [name, diff, cat, desc] of EARTH_SCIENCE) {
    add(
      diff,
      `지구과학(${cat})에서 ${desc}을(를) 무엇이라 하는가?`,
      name,
      allEarthNames,
      `${cat} 영역의 핵심 개념입니다.`,
      `${name}은(는) ${desc}입니다.`
    );
    const nextDiff = diff === 'intro' ? 'beginner' : diff === 'beginner' ? 'intermediate' : 'advanced';
    add(
      nextDiff,
      `지구과학의 '${name}'에 대한 설명으로 옳은 것은?`,
      desc,
      allEarthDescs,
      `${cat} 분야의 용어입니다.`,
      `${name}은(는) ${desc}입니다.`
    );
  }

  for (const [diff, q, ans, pool, hint, exp] of ASTRO_EARTH_EXTRAS) {
    add(diff, q, ans, pool, hint, exp);
  }
}

