function buildExtraIntermediateSection(add) {
  const groups = [
    ['신소재·합금', MATERIALS_ALLOYS],
    ['의학·생명공학', MEDICINE_BIOTECH],
    ['첨단공학·미래기술', ENGINEERING_NEXTGEN]
  ];
  for (const [domainLabel, list] of groups) {
    const names = list.map((x) => x[0]);
    const descs = list.map((x) => x[3]);
    for (const [name, diff, cat, desc] of list) {
      add(
        diff,
        `${domainLabel}(${cat}) 분야에서 ${desc}을(를) 무엇이라 하는가?`,
        name,
        names,
        `${cat}와(과) 관련된 핵심 과학·기술 용어입니다.`,
        `${name}은(는) ${desc}입니다.`
      );
      add(
        diff,
        `${domainLabel} 용어 '${name}'에 대한 설명으로 가장 옳은 것은?`,
        desc,
        descs,
        `${cat} 분야의 기술 또는 의학 개념입니다.`,
        `${name}은(는) ${desc}입니다.`
      );
    }
  }
}

module.exports = function generate() {
  const { rows, add } = createCollector();
  buildChemistrySection(add);
  buildPhysicsChemSection(add);
  buildBiologySection(add);
  buildAstroEarthSection(add);
  buildMathSection(add);
  buildTechSection(add);
  buildExtraIntermediateSection(add);
  return rows;
};
